-- 에코디교회 문서보관: 문서 바로 편집(본문 HTML)과 저장 이력
CREATE TABLE IF NOT EXISTS church_document_contents (doc_id TEXT PRIMARY KEY, html TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS church_document_revisions (id TEXT PRIMARY KEY, doc_id TEXT NOT NULL, html TEXT NOT NULL, saved_at TEXT NOT NULL, saved_by TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_church_document_revisions_doc ON church_document_revisions(doc_id, saved_at);
INSERT OR IGNORE INTO church_document_contents (doc_id,html,updated_at,updated_by) VALUES ('cdoc-2027-selfreliance-00','<p class="c"><span style="font-size:15.0pt"><b>2027년도 목포노회 동반성장 자립화교회 지원신청 — 제출서류 체크리스트 (에코디교회)</b></span></p><p><span style="font-size:9.5pt"><b>제출 기한: 2026년 11월 23일(월)까지 엄수  |  제출처: 목포노회 동반목회지원위원회</b></span></p><p><span style="font-size:8.5pt">주소: (58560) 무안군 삼향읍 석매길 10  |  전화 061-244-5006  |  팩스 061-244-5706  |  이메일 dom6966@hanmail.net</span></p><p><span style="font-size:8.5pt">근거: 목포노회 동반목회지원 운영 규정 제13조 / 공문 시행 목동위-2026-7 (2026.11.3.)</span></p><table><colgroup><col style="width:6.23%"><col style="width:19.71%"><col style="width:31.13%"><col style="width:19.71%"><col style="width:23.22%"></colgroup><tr><td class="h"><p class="c"><span style="font-size:8.5pt"><b>번호</b></span></p></td><td class="h"><p class="c"><span style="font-size:8.5pt"><b>구분</b></span></p></td><td class="h"><p class="c"><span style="font-size:8.5pt"><b>주요내용</b></span></p></td><td class="h"><p class="c"><span style="font-size:8.5pt"><b>준비 상태</b></span></p></td><td class="h"><p class="c"><span style="font-size:8.5pt"><b>할 일·발급처</b></span></p></td></tr><tr><td><p class="c"><span style="font-size:8.5pt">1</span></p></td><td><p><span style="font-size:8.5pt">신청서(서식 1-1)</span></p></td><td><p><span style="font-size:8.5pt">기본정보·교회현황·소득·가족·개인정보 동의</span></p></td><td><p><span style="font-size:8.5pt">초안 완료 (빈칸: </span><span style="font-size:8.5pt"><b><span class="need">확인필요</span></b></span><span style="font-size:8.5pt">)</span></p></td><td><p><span style="font-size:8.5pt">빨간 &quot;</span><span style="font-size:8.5pt"><b><span class="need">확인필요</span></b></span><span style="font-size:8.5pt">&quot; 칸 채우고 서명·날인</span></p></td></tr><tr><td><p class="c"><span style="font-size:8.5pt">1</span></p></td><td><p><span style="font-size:8.5pt">목회계획서(서식 1-2)</span></p></td><td><p><span style="font-size:8.5pt">지역현황·목표·월별계획·지역역할·요청사항</span></p></td><td><p><span style="font-size:8.5pt">초안 완료</span></p></td><td><p><span style="font-size:8.5pt">내용 확인, 요청 지원금액 기재</span></p></td></tr><tr><td><p class="c"><span style="font-size:8.5pt">2</span></p></td><td><p><span style="font-size:8.5pt">건강보험료 납부확인서</span></p></td><td><p><span style="font-size:8.5pt">본인 + 배우자 모두</span></p></td><td><p><span style="font-size:8.5pt">본인 발급·등록 완료(11/9)</span></p></td><td><p><span style="font-size:8.5pt">국민건강보험공단 nhis.or.kr → 보험료 납부확인서 / 정부24 / The건강보험 앱 (무료)</span></p></td></tr><tr><td><p class="c"><span style="font-size:8.5pt">3</span></p></td><td><p><span style="font-size:8.5pt">소득증명서</span></p></td><td><p><span style="font-size:8.5pt">목회자 소득 (자비량 소득 포함)</span></p></td><td><p><span style="font-size:8.5pt">발급·등록 완료(11/9)</span></p></td><td><p><span style="font-size:8.5pt">홈택스 hometax.go.kr → 민원증명 → 소득금액증명 (2025년 귀속)</span></p></td></tr><tr><td><p class="c"><span style="font-size:8.5pt">4</span></p></td><td><p><span style="font-size:8.5pt">교회 내규(정관)</span></p></td><td><p><span style="font-size:8.5pt">고유번호 발급 때 낸 정관 우선</span></p></td><td><p><span style="font-size:8.5pt">초안 갱신(에코디 정신 반영)</span></p></td><td><p><span style="font-size:8.5pt">기존 정관 있으면 그것 사용, 없으면 초안을 공동의회에서 의결</span></p></td></tr><tr><td><p class="c"><span style="font-size:8.5pt">5</span></p></td><td><p><span style="font-size:8.5pt">교회명의 통장사본</span></p></td><td><p><span style="font-size:8.5pt">농협 355-0088-5391-83, 예금주 에코디교회</span></p></td><td><p><span style="font-size:8.5pt">등록 완료(11/9)</span></p></td><td><p><span style="font-size:8.5pt">문서보관 05</span></p></td></tr><tr><td><p class="c"><span style="font-size:8.5pt">6</span></p></td><td><p><span style="font-size:8.5pt">공동의회 회의록</span></p></td><td><p><span style="font-size:8.5pt">제직회 미조직 → 공동의회록, 결산 금액 표시</span></p></td><td><p><span style="font-size:8.5pt">초안 준비 · 11/8 주보 광고 완료</span></p></td><td><p><span style="font-size:8.5pt">11/15 공동의회에서 2024·2025 결산·예산·정관·공간 무상사용·지원신청 의결 후 서명</span></p></td></tr><tr><td><p class="c"><span style="font-size:8.5pt">참고</span></p></td><td><p><span style="font-size:8.5pt">결산 및 교인현황표</span></p></td><td><p><span style="font-size:8.5pt">2024·2025년 결산 2,400,000원, 세례교인 8명, 예배처 월세 0원</span></p></td><td><p><span style="font-size:8.5pt">작성 완료</span></p></td><td><p><span style="font-size:8.5pt">6) 회의록과 함께 첨부</span></p></td></tr></table><p><span style="font-size:11.0pt"><b>일정 제안</b></span></p><p><span style="font-size:9.5pt">· 11/9(월)~11/13(금): 건강보험료 납부확인서·소득금액증명 발급, 통장사본 준비, 결산 자료 정리</span></p><p><span style="font-size:9.5pt">· 11/8(주일): 주보·예배 PPT 교회소식으로 공동의회 광고 (반영 완료)</span></p><p><span style="font-size:9.5pt">· 11/15(주일): 주일모임 후 공동의회 — 결산·예산·정관·공간 무상사용·지원신청 의결</span></p><p><span style="font-size:9.5pt">· 11/16(월)~11/20(금): 서류 최종 확인, 서명·날인 후 제출 (기한 3일 전 여유)</span></p><p><span style="font-size:11.0pt"><b>주의할 점</b></span></p><p><span style="font-size:9.5pt">· 자비량 소득(에코디비즈)은 신청서와 소득증명서 금액이 서로 맞아야 합니다.</span></p><p><span style="font-size:9.5pt">· 에코디비즈의 교회 공간 일부 무상사용을 신청서 비고에 적고 공동의회 안건으로 올렸습니다. 목회자 본인 사업이므로 공동의회 승인 기록을 남겨 두는 것이 투명합니다.</span></p><p><span style="font-size:9.5pt">· 드라이브의 「고유번호증.pdf」는 라온시우터 아카데미 것이고, 에코디교회 고유번호증(307-82-82097)·정관 파일은 드라이브에서 찾지 못했습니다.</span></p><p><span style="font-size:9.5pt">· 시찰 이름(함무시찰), 노회지원 연차, 2024년 지원금 여부는 노회 사무실에 확인이 필요합니다.</span></p>','2026-11-23T14:30:00Z','claude');
